import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.core.io.ClassPathResource;
import org.springframework.stereotype.Service;
import java.io.File;
import java.io.FileWriter;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.sql.*;
import java.util.*;

@Service
public class QueryService {

    @Autowired
    private DataSource dataSource;

    public void executeQueryAndSaveResults() throws IOException {
        String query = readQueryFromFile("query.sql");
        List<String> results = executeQuery(query);
        saveResultsToFile(results, "results.txt");
    }

    private String readQueryFromFile(String fileName) throws IOException {
        ClassPathResource resource = new ClassPathResource(fileName);
        return new String(Files.readAllBytes(resource.getFile().toPath()));
    }

    private List<String> executeQuery(String query) throws SQLException {
        List<String> results = new ArrayList<>();
        try (Connection connection = dataSource.getConnection();
             PreparedStatement preparedStatement = connection.prepareStatement(query);
             ResultSet resultSet = preparedStatement.executeQuery()) {
            ResultSetMetaData metaData = resultSet.getMetaData();
            int columnCount = metaData.getColumnCount();
            while (resultSet.next()) {
                StringBuilder row = new StringBuilder();
                for (int i = 1; i <= columnCount; i++) {
                    row.append(metaData.getColumnName(i)).append(": ").append(resultSet.getString(i)).append(", ");
                }
                row.setLength(row.length() - 2); // Remove the last comma and space
                results.add(row.toString());
            }
        }
        return results;
    }

    private void saveResultsToFile(List<String> results, String fileName) throws IOException {
        File file = new File(fileName);
        try (FileWriter writer = new FileWriter(file)) {
            for (String result : results) {
                writer.write(result + System.lineSeparator());
            }
        }
    }
}

